59	/// Destruct the given value into the pattern and apply the function to each binding.
60	fn destructure_impl<F>(
61	    vm: &mut Vm,
62	    pattern: ast::Pattern,
63	    value: Value,
64	    f: &mut F,
65	) -> SourceResult<()>
66	where
67	    F: Fn(&mut Vm, ast::Expr, Value) -> SourceResult<()>,
