374	    // Missing fields may actually be present if they are settable parameters
375	    // on elements accessed with context, e.g. `block.stroke`.
376	    if let Value::Func(func) = &target
377	        && let Some(element) = func.to_element()
378	        && let Some(field_accessor) = element.settable_field_accessor(field)
