1	//! Handles special built-in methods on values.
2	
3	use ecow::{EcoString, eco_format};
4	use typst_library::diag::{At, SourceResult};
5	use typst_library::foundations::{Args, Str, Type, Value};
6	use typst_syntax::Span;
7	
8	/// Whether a specific method is mutating.
9	pub(crate) fn is_mutating_method(method: &str) -> bool {
10	    matches!(method, "push" | "pop" | "insert" | "remove")
11	}
12	
13	/// Mutating methods for dictionaries.
14	pub(crate) fn is_dict_mutating_method(method: &str) -> bool {
15	    matches!(method, "insert" | "remove")
16	}
17	
18	/// Whether a specific method is an accessor.
19	pub(crate) fn is_accessor_method(method: &str) -> bool {
20	    matches!(method, "first" | "last" | "at")
21	}
22	
23	/// Call a mutating method on a value.
24	pub(crate) fn call_method_mut(
25	    value: &mut Value,
26	    method: &str,
27	    mut args: Args,
28	    span: Span,
29	) -> SourceResult<Value> {
30	    let ty = value.ty();
31	    let missing = || Err(missing_method(ty, method)).at(span);
32	    let mut output = Value::None;
33	
34	    match value {
35	        Value::Array(array) => match method {
36	            "push" => array.push(args.expect("value")?),
37	            "pop" => output = array.pop().at(span)?,
38	            "insert" => {
39	                array.insert(args.expect("index")?, args.expect("value")?).at(span)?;
40	            }
41	            "remove" => {
42	                output = array
43	                    .remove(args.expect("index")?, args.named("default")?)
44	                    .at(span)?;
45	            }
46	            _ => return missing(),
47	        },
48	
49	        Value::Dict(dict) => match method {
50	            "insert" => dict.insert(args.expect::<Str>("key")?, args.expect("value")?),
51	            "remove" => {
52	                output =
53	                    dict.remove(args.expect("key")?, args.named("default")?).at(span)?;
54	            }
55	            _ => return missing(),
56	        },
57	
58	        _ => return missing(),
59	    }
60	
61	    args.finish()?;
62	    Ok(output)
63	}
64	
65	/// Call an accessor method on a value.
66	pub(crate) fn call_method_access<'a>(
67	    value: &'a mut Value,
68	    method: &str,
69	    mut args: Args,
70	    span: Span,
71	) -> SourceResult<&'a mut Value> {
72	    let ty = value.ty();
73	    let temp_or_missing = || {
74	        Err(if ty.scope().get(method).is_some() {
75	            "cannot mutate a temporary value".into()
76	        } else {
77	            missing_method(ty, method)
78	        })
79	        .at(span)
80	    };
81	
82	    let slot = match value {
83	        Value::Array(array) => match method {
